  background: linear-gradient(180deg, rgb(16 28 51 / 0.72), rgb(12 21 38 / 0.92));
  border: 1px solid var(--color-line);
  border-radius: 14px;
}

.eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-muted);
}

@keyframes pulse-ring {
  0% {
    transform: scale(1);
    opacity: 0.7;
  }
  100% {
    transform: scale(2.4);
    opacity: 0;
  }
}
.pulse-ring {
  transform-box: fill-box;
  transform-origin: center;
  animation: pulse-ring 1.6s ease-out infinite;
}

@keyframes flow-dash {
  to {
    stroke-dashoffset: -24;
  }
}
.flow-line {
  stroke-dasharray: 6 6;
  animation: flow-dash 0.9s linear infinite;
}

@keyframes feed-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.feed-in {
  animation: feed-in 0.35s ease-out both;
}

@keyframes glow {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgb(45 212 191 / 0);
  }
  50% {
    box-shadow: 0 0 28px 2px rgb(45 212 191 / 0.45);
  }
}
.glow-teal {
  animation: glow 1.8s ease-in-out infinite;
}

@keyframes attention {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgb(251 191 36 / 0);
  }
  50% {
    box-shadow: 0 0 0 6px rgb(251 191 36 / 0.35);
