            dot={false}
            isAnimationActive={false}
            connectNulls={false}
            filter={diverged ? `url(#glow-${kind})` : undefined}
          />
          {kind === 'saturation' && (
            <Line
              dataKey="forecastSat"
              stroke="#99f6e4"
