p="src/lib/demo.ts"; s=open(p,encoding="utf-8").read()
old='''    const forecastVisible = made !== undefined && made.tick <= playhead && p.tick > playhead - FORECAST_LEAD_TICKS'''
assert old in s
s=s.replace(old,'''    // The dotted forecast runs from the cursor 2 hours ahead: each point was forecast
    // 8 ticks earlier, so every value shown was already known at the playhead.
    const forecastVisible = made !== undefined && made.tick <= playhead && p.tick >= playhead''')
old2='''/** Fixed y-axis maxima for the run, so axes never jump while the playhead moves. */
export function axisMaxima(state: DashboardState): { saturation: number; hours: number } {
  const focus = state.series.find((s) => s.hospital_id === state.curves.focus_hospital_id)
  const { start, last } = windowRange(state)
  let sat = 100
  for (const track of ['baseline', 'triagex'] as const) {
    for (const p of focus?.[track] ?? []) {
      if (p.tick >= start - FORECAST_LEAD_TICKS && p.tick <= last) {
        sat = Math.max(sat, p.saturation_pct, p.forecast_saturation_pct)
      }
    }
  }
  const hours = Math.max(1, ...state.curves.points.map((p) => p.baseline_ambulance_hours_cumulative))
  return { saturation: Math.ceil(sat / 20) * 20, hours: Math.ceil(hours / 5) * 5 }
}'''
assert old2 in s
s=s.replace(old2,'''/**
 * Fixed y-axis maxima for the run, so axes never jump while the playhead moves. Scaled to
 * the observed values; forecast spikes above it are clipped visually (tooltips keep the
 * exact value).
 */
